-- ============================================================================================
-- Hamsha PRODUCTION release — migrations 0007 → 0008 → 0009 → 0010 → 0011 → 0012 → 0013 → 0014 in ONE transaction.
-- Generated by supabase/release/build.py — do not edit by hand. Paste ALL of it, run once.
-- Success = «Success. No rows returned» (or the final summary row). Any error = NOTHING was changed.
-- ============================================================================================
begin;
set local lock_timeout = '5s';
set local statement_timeout = '180s';

-- ---------- guard: right database, right moment ----------
do $$ begin
  if to_regclass('public.tasks') is null or to_regclass('public.invitations') is null then
    raise exception 'RELEASE ABORTED: the 0001–0006 base is missing — wrong database?';
  end if;
  if to_regclass('public.posts') is not null then
    raise exception 'RELEASE ABORTED: social (0007) already exists here — this release was applied before';
  end if;
end $$;

-- ---------- old data: counted before, compared after ----------
create temp table release_before on commit drop as
  select * from (values ('organizations', (select count(*) from organizations)), ('profiles', (select count(*) from profiles)), ('clients', (select count(*) from clients)), ('projects', (select count(*) from projects)), ('tasks', (select count(*) from tasks)), ('task_parts', (select count(*) from task_parts)), ('messages', (select count(*) from messages)), ('invitations', (select count(*) from invitations)), ('attachments', (select count(*) from attachments))) v(tbl, n);


-- ================================ 0007_social.sql ================================
-- ============================================================================
-- 0007 — «السوشل» phase 1 (2026-10-28, council 20261028-032546-200e, Yousef's pick ٤):
-- a social post goes  draft → sent (to the client) → approved | changes → published.
--   • Every upload is a FROZEN version (image + caption). The client's decision is bound to ONE version
--     number; a new version puts the post back to `draft` and needs to be sent again (approval never carries over).
--   • The client NEVER reads the raw tables: two owner-rights views (client_posts, client_post_versions)
--     expose exactly what the approval screen shows — no people, no internal notes — and the ONLY write a
--     client has is decide_post() (security definer, checks everything itself).
--   • Team (admin / creative) read posts they are involved in; creatives may create posts + versions for
--     clients they have a task with; status transitions are admin-only and enforced by posts_status_guard.
--   • Media lives in the private bucket `post-media` under <org>/<client>/<post>/<n>.<ext> (applied on
--     Supabase only — the plain-Postgres CI has no storage schema).
-- Phase 1 publishes MANUALLY: the admin pastes the live link («تم النشر»). Auto-publish, video, per-second
-- notes, a backup approver and the 5-hour reminder are deliberately NOT here.
-- ============================================================================

create type post_platform as enum ('instagram', 'tiktok', 'snapchat', 'linkedin', 'x');
create type post_format   as enum ('square', 'portrait', 'story');          -- 1:1 · 4:5 · 9:16
create type post_status   as enum ('draft', 'sent', 'approved', 'changes', 'published');
create type post_decision as enum ('approved', 'changes');

create table posts (
  id              uuid primary key default gen_random_uuid(),
  org_id          uuid not null references organizations(id) on delete cascade,
  client_id       uuid not null references clients(id) on delete cascade,
  task_id         uuid references tasks(id) on delete set null,
  title           text not null check (length(title) between 1 and 200),
  platform        post_platform not null default 'instagram',
  format          post_format not null default 'square',
  status          post_status not null default 'draft',
  current_version integer not null default 0,
  sent_at         timestamptz,
  published_url   text check (published_url is null or published_url ~ '^https?://'),
  published_at    timestamptz,
  created_by      uuid references profiles(id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index on posts (client_id, status);
create index on posts (org_id, updated_at desc);

create table post_versions (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references organizations(id) on delete cascade,
  post_id       uuid not null references posts(id) on delete cascade,
  number        integer not null,
  image_path    text not null check (length(image_path) between 1 and 500),
  caption       text not null default '' check (length(caption) <= 4000),
  note          text check (note is null or length(note) <= 2000),          -- team → client, shown with the version
  decision      post_decision,
  decision_note text check (decision_note is null or length(decision_note) <= 4000),
  decided_by    uuid references profiles(id) on delete set null,
  decided_at    timestamptz,
  created_by    uuid references profiles(id) on delete set null,
  created_at    timestamptz not null default now(),
  unique (post_id, number)
);
create index on post_versions (post_id, number desc);

-- ---------- visibility helper (security definer → no RLS recursion) ----------
create or replace function can_read_post(pid uuid) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare p record; r user_role := current_role_();
begin
  select org_id, client_id, task_id, created_by into p from posts where id = pid;
  if p is null or p.org_id is distinct from current_org() then return false; end if;
  if r = 'admin' then return true; end if;
  if r = 'client' then return p.client_id = current_client(); end if;
  if r = 'creative' then
    return p.created_by = auth.uid()
        or (p.task_id is not null and can_read_task(p.task_id))
        or exists (select 1 from tasks t where t.client_id = p.client_id and can_read_task(t.id));
  end if;
  return false;
end $$;
revoke execute on function can_read_post(uuid) from public, anon;
grant  execute on function can_read_post(uuid) to authenticated;

-- a creative may work on a client they have a task with (owner or assignee)
create or replace function works_with_client(cid uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select current_role_() = 'admin'
      or (current_role_() = 'creative' and exists (select 1 from tasks t where t.client_id = cid and can_read_task(t.id)))
$$;
revoke execute on function works_with_client(uuid) from public, anon;
grant  execute on function works_with_client(uuid) to authenticated;

-- ---------- consistency + the state machine ----------
create or replace function posts_consistency() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from clients where id = new.client_id and org_id = new.org_id) then
    raise exception 'client outside organization';
  end if;
  if new.task_id is not null and not exists (select 1 from tasks where id = new.task_id and client_id = new.client_id and org_id = new.org_id) then
    raise exception 'task belongs to another client';
  end if;
  if tg_op = 'INSERT' then
    -- a post is born as an empty draft; versions and status come later, never from the insert
    new.status := 'draft'; new.current_version := 0; new.sent_at := null; new.published_url := null; new.published_at := null;
    new.created_by := auth.uid();
  end if;
  return new;
end $$;
create trigger posts_consistency before insert or update on posts
  for each row execute function posts_consistency();

-- Allowed transitions (admin only; everything else raises). Internal trigger writes carry hamsha.sys = '1'.
create or replace function posts_status_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare sys boolean := coalesce(current_setting('hamsha.sys', true), '') = '1';
begin
  new.updated_at := now();
  if sys then return new; end if;
  if new.id is distinct from old.id or new.org_id is distinct from old.org_id or new.client_id is distinct from old.client_id
     or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception 'post identity cannot change';
  end if;
  if new.current_version is distinct from old.current_version then
    raise exception 'current_version is set by uploading a version';
  end if;
  if current_role_() <> 'admin' then
    raise exception 'only admins change posts';
  end if;
  if new.status is distinct from old.status then
    if old.status = 'draft' and new.status = 'sent' then
      if old.current_version = 0 then raise exception 'upload a version before sending'; end if;
      new.sent_at := now();
    elsif old.status = 'sent' and new.status = 'draft' then
      new.sent_at := null;                                   -- withdrawn before the client decided
    elsif old.status = 'approved' and new.status = 'published' then
      if new.published_url is null then raise exception 'published_url is required'; end if;
      new.published_at := now();
    else
      raise exception 'transition % → % is not allowed', old.status, new.status;
    end if;
  elsif new.published_url is distinct from old.published_url and old.status <> 'published' then
    raise exception 'published_url only on a published post';
  end if;
  if new.sent_at is distinct from old.sent_at and new.status = old.status then raise exception 'sent_at is derived'; end if;
  if new.published_at is distinct from old.published_at and new.status = old.status then raise exception 'published_at is derived'; end if;
  return new;
end $$;
create trigger posts_status_guard before update on posts
  for each row execute function posts_status_guard();

-- A new version: number is assigned here, the post returns to draft (the old approval never carries over).
create or replace function post_versions_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare p record;
begin
  select org_id, status, current_version into p from posts where id = new.post_id;
  if p is null then raise exception 'unknown post'; end if;
  if p.org_id <> new.org_id then raise exception 'organization mismatch'; end if;
  if p.status = 'published' then raise exception 'a published post cannot change'; end if;
  new.number := p.current_version + 1;
  new.created_by := auth.uid();
  new.decision := null; new.decision_note := null; new.decided_by := null; new.decided_at := null;
  perform set_config('hamsha.sys', '1', true);
  update posts set current_version = new.number, status = 'draft', sent_at = null where id = new.post_id;
  perform set_config('hamsha.sys', '', true);
  return new;
end $$;
create trigger post_versions_insert before insert on post_versions
  for each row execute function post_versions_insert();

-- Versions are frozen: nothing changes after the insert except through decide_post().
create or replace function post_versions_frozen() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if coalesce(current_setting('hamsha.sys', true), '') = '1' then return new; end if;
  raise exception 'versions are frozen';
end $$;
create trigger post_versions_frozen before update on post_versions
  for each row execute function post_versions_frozen();

-- ---------- the client's ONLY write ----------
create or replace function decide_post(p_version uuid, p_decision post_decision, p_note text default null)
returns void
language plpgsql security definer set search_path = public as $$
declare v record; p record;
begin
  if current_role_() <> 'client' then raise exception 'only clients decide'; end if;
  select id, post_id, number, decision into v from post_versions where id = p_version;
  if v is null then raise exception 'unknown version'; end if;
  select id, org_id, client_id, status, current_version into p from posts where id = v.post_id;
  if p.org_id <> current_org() or p.client_id <> current_client() then raise exception 'not your post'; end if;
  if p.status <> 'sent' then raise exception 'post is not awaiting your decision'; end if;
  if v.number <> p.current_version then raise exception 'only the current version can be decided'; end if;
  if v.decision is not null then raise exception 'already decided'; end if;
  if p_decision = 'changes' and length(trim(coalesce(p_note, ''))) = 0 then raise exception 'say what to change'; end if;
  perform set_config('hamsha.sys', '1', true);
  update post_versions set decision = p_decision, decision_note = nullif(trim(coalesce(p_note, '')), ''), decided_by = auth.uid(), decided_at = now() where id = v.id;
  update posts set status = p_decision::text::post_status where id = p.id;
  perform set_config('hamsha.sys', '', true);
end $$;
revoke execute on function decide_post(uuid, post_decision, text) from public, anon;
grant  execute on function decide_post(uuid, post_decision, text) to authenticated;

-- ---------- RLS ----------
alter table posts         enable row level security;
alter table post_versions enable row level security;
revoke all on posts, post_versions from anon;
grant select, insert, update, delete on posts, post_versions to authenticated;

create policy posts_read on posts for select
  using (is_team() and can_read_post(id));
create policy posts_admin_write on posts for all
  using (org_id = current_org() and current_role_() = 'admin')
  with check (org_id = current_org() and current_role_() = 'admin');
create policy posts_creative_insert on posts for insert
  with check (org_id = current_org() and current_role_() = 'creative' and works_with_client(client_id));

create policy versions_read on post_versions for select
  using (is_team() and can_read_post(post_id));
create policy versions_team_insert on post_versions for insert
  with check (org_id = current_org() and is_team() and can_read_post(post_id));
create policy versions_admin_delete on post_versions for delete
  using (org_id = current_org() and current_role_() = 'admin');
-- no update policy: versions are frozen (decide_post is security definer)

-- ---------- client views: the ONLY way a client reads posts (no people, no internal fields) ----------
create view client_posts with (security_invoker = false) as
  select id, client_id, task_id, title, platform, format, status, current_version, sent_at, published_url, published_at, created_at, updated_at
  from posts
  where current_role_() = 'client' and client_id = current_client();

create view client_post_versions with (security_invoker = false) as
  select v.id, v.post_id, v.number, v.image_path, v.caption, v.note, v.decision, v.decision_note, v.decided_at, v.created_at
  from post_versions v
  join posts p on p.id = v.post_id
  where current_role_() = 'client' and p.client_id = current_client();

revoke all on client_posts, client_post_versions from public, anon;
grant select on client_posts, client_post_versions to authenticated;

-- ---------- audit + realtime ----------
create trigger posts_audit    after insert or update or delete on posts         for each row execute function audit();
create trigger versions_audit after insert or update or delete on post_versions for each row execute function audit();
alter publication supabase_realtime add table posts, post_versions;

-- ---------- storage: private bucket `post-media` (<org>/<client>/<post>/<n>.<ext>) ----------
do $$
begin
  if to_regclass('storage.objects') is null then
    raise notice 'storage schema absent (local CI) — skipping post-media policies';
    return;
  end if;
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('post-media', 'post-media', false, 10 * 1024 * 1024, array['image/png', 'image/jpeg', 'image/webp'])
    on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

  execute 'drop policy if exists hamsha_post_media_read on storage.objects';
  execute $p$create policy hamsha_post_media_read on storage.objects for select to authenticated
    using (bucket_id = 'post-media' and (storage.foldername(name))[1] = current_org()::text
           and (current_role_() in ('admin', 'creative') or (storage.foldername(name))[2] = current_client()::text))$p$;
  execute 'drop policy if exists hamsha_post_media_write on storage.objects';
  execute $p$create policy hamsha_post_media_write on storage.objects for insert to authenticated
    with check (bucket_id = 'post-media' and (storage.foldername(name))[1] = current_org()::text and current_role_() in ('admin', 'creative'))$p$;
  execute 'drop policy if exists hamsha_post_media_delete on storage.objects';
  execute $p$create policy hamsha_post_media_delete on storage.objects for delete to authenticated
    using (bucket_id = 'post-media' and (storage.foldername(name))[1] = current_org()::text and current_role_() = 'admin')$p$;
end $$;



-- ================================ 0008_social_v2.sql ================================
-- ============================================================================
-- 0008 — «السوشل» ١.٥ (2026-10-29, council 20261029-021136-0526 after Yousef's staging test of phase 1):
--   1. SECURITY — the client saw unsent drafts: client_posts now hides `draft` posts, and client_post_versions
--      shows ONLY versions that were actually sent (server-set post_versions.sent_at, stamped by the status
--      guard when the admin sends). A new, not-yet-sent version of an already-sent post never leaks (Codex).
--      decide_post() additionally requires the version to carry sent_at.
--   2. CAROUSEL — a version holds an ORDERED set of images: post_versions.image_paths text[] (index 0 = cover),
--      1..20 items (Instagram's limit since Aug 2024; the UI caps per platform, e.g. X = 4). The whole set is
--      frozen with the version; files are never overwritten (every upload gets a new path).
--   3. CLIENT ACCOUNTS — client_accounts (one row per platform account: handle, display name, avatar, bio)
--      so the preview shows the real account; posts.account_id links a post to one of them (same client,
--      same platform — enforced). Avatars live in the public bucket `client-logos` under
--      <org>/<client>/accounts/<rnd>.<ext> (0006 policies already cover that prefix).
-- No official platform logos anywhere (Meta / TikTok brand rules); no fake likes, comments or followers.
-- ============================================================================

-- ---------- 2. carousel: image_path → image_paths[] ----------
alter table post_versions add column image_paths text[] not null default '{}';
-- backfill existing rows (versions are frozen: the trigger lets only internal writes through)
do $$
begin
  perform set_config('hamsha.sys', '1', true);
  update post_versions set image_paths = array[image_path];
  perform set_config('hamsha.sys', '', true);
end $$;
alter table post_versions add column sent_at timestamptz;                      -- 1. stamped by the status guard, never by a client
-- versions that were already in front of a client before 0008: any decided version, and the current version
-- of a post that left draft (sent / approved / changes / published) — the client must keep seeing them
do $$
begin
  perform set_config('hamsha.sys', '1', true);
  update post_versions v set sent_at = coalesce(v.decided_at, p.sent_at, p.published_at, v.created_at)
    from posts p where p.id = v.post_id and v.sent_at is null
      and (v.decision is not null or (p.status <> 'draft' and v.number = p.current_version));
  perform set_config('hamsha.sys', '', true);
end $$;
alter table post_versions add constraint post_versions_media_count check (cardinality(image_paths) between 1 and 20);
alter table post_versions alter column image_paths drop default;

-- the client views depend on image_path: rebuild them further down
drop view if exists client_post_versions;
drop view if exists client_posts;
alter table post_versions drop column image_path;

-- every path is a non-empty storage key
create or replace function post_versions_check_paths(paths text[]) returns boolean
language sql immutable as $$
  select paths is not null and cardinality(paths) between 1 and 20
     and not exists (select 1 from unnest(paths) p where p is null or length(p) not between 1 and 500)
$$;
alter table post_versions add constraint post_versions_media_paths check (post_versions_check_paths(image_paths));

-- ---------- 3. client accounts ----------
create table client_accounts (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references organizations(id) on delete cascade,
  client_id     uuid not null references clients(id) on delete cascade,
  platform      post_platform not null,
  handle        text not null check (handle ~ '^[A-Za-z0-9._-]{1,60}$'),      -- without the @
  display_name  text not null check (length(display_name) between 1 and 80),
  avatar_path   text check (avatar_path is null or length(avatar_path) between 1 and 500),
  bio           text check (bio is null or length(bio) <= 300),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (client_id, platform, handle)
);
create index on client_accounts (client_id, platform);

create or replace function client_accounts_consistency() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from clients where id = new.client_id and org_id = new.org_id) then
    raise exception 'client outside organization';
  end if;
  if tg_op = 'UPDATE' and (new.id is distinct from old.id or new.org_id is distinct from old.org_id or new.client_id is distinct from old.client_id or new.created_at is distinct from old.created_at) then
    raise exception 'account identity cannot change';
  end if;
  new.handle := ltrim(trim(new.handle), '@');
  new.updated_at := now();
  return new;
end $$;
create trigger client_accounts_consistency before insert or update on client_accounts
  for each row execute function client_accounts_consistency();

alter table posts add column account_id uuid references client_accounts(id) on delete set null;
create index on posts (account_id);

-- the account must belong to the post's client and platform
create or replace function posts_consistency() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from clients where id = new.client_id and org_id = new.org_id) then
    raise exception 'client outside organization';
  end if;
  if new.task_id is not null and not exists (select 1 from tasks where id = new.task_id and client_id = new.client_id and org_id = new.org_id) then
    raise exception 'task belongs to another client';
  end if;
  if new.account_id is not null and not exists (select 1 from client_accounts a where a.id = new.account_id and a.client_id = new.client_id and a.platform = new.platform) then
    raise exception 'account belongs to another client or platform';
  end if;
  if tg_op = 'INSERT' then
    new.status := 'draft'; new.current_version := 0; new.sent_at := null; new.published_url := null; new.published_at := null;
    new.created_by := auth.uid();
  end if;
  return new;
end $$;

alter table client_accounts enable row level security;
revoke all on client_accounts from anon;
grant select, insert, update, delete on client_accounts to authenticated;
create policy accounts_team_read on client_accounts for select
  using (org_id = current_org() and (current_role_() = 'admin' or (current_role_() = 'creative' and works_with_client(client_id))));
create policy accounts_client_read on client_accounts for select
  using (org_id = current_org() and current_role_() = 'client' and client_id = current_client());
create policy accounts_admin_write on client_accounts for all
  using (org_id = current_org() and current_role_() = 'admin')
  with check (org_id = current_org() and current_role_() = 'admin');

create trigger accounts_audit after insert or update or delete on client_accounts for each row execute function audit();
alter publication supabase_realtime add table client_accounts;

-- ---------- 1. sending stamps the CURRENT version; everything else as in 0007 ----------
create or replace function posts_status_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare sys boolean := coalesce(current_setting('hamsha.sys', true), '') = '1';
begin
  new.updated_at := now();
  if sys then return new; end if;
  if new.id is distinct from old.id or new.org_id is distinct from old.org_id or new.client_id is distinct from old.client_id
     or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception 'post identity cannot change';
  end if;
  if new.current_version is distinct from old.current_version then
    raise exception 'current_version is set by uploading a version';
  end if;
  if current_role_() <> 'admin' then
    raise exception 'only admins change posts';
  end if;
  if new.status is distinct from old.status then
    if old.status = 'draft' and new.status = 'sent' then
      if old.current_version = 0 then raise exception 'upload a version before sending'; end if;
      new.sent_at := now();
      perform set_config('hamsha.sys', '1', true);
      update post_versions set sent_at = coalesce(sent_at, now()) where post_id = new.id and number = old.current_version;
      perform set_config('hamsha.sys', '', true);
    elsif old.status = 'sent' and new.status = 'draft' then
      new.sent_at := null;                                   -- withdrawn before the client decided (the post hides again)
    elsif old.status = 'approved' and new.status = 'published' then
      if new.published_url is null then raise exception 'published_url is required'; end if;
      new.published_at := now();
    else
      raise exception 'transition % → % is not allowed', old.status, new.status;
    end if;
  elsif new.published_url is distinct from old.published_url and old.status <> 'published' then
    raise exception 'published_url only on a published post';
  end if;
  if new.sent_at is distinct from old.sent_at and new.status = old.status then raise exception 'sent_at is derived'; end if;
  if new.published_at is distinct from old.published_at and new.status = old.status then raise exception 'published_at is derived'; end if;
  return new;
end $$;

-- a new version is never "sent" at birth
create or replace function post_versions_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare p record;
begin
  select org_id, status, current_version into p from posts where id = new.post_id;
  if p is null then raise exception 'unknown post'; end if;
  if p.org_id <> new.org_id then raise exception 'organization mismatch'; end if;
  if p.status = 'published' then raise exception 'a published post cannot change'; end if;
  new.number := p.current_version + 1;
  new.created_by := auth.uid();
  new.sent_at := null;
  new.decision := null; new.decision_note := null; new.decided_by := null; new.decided_at := null;
  perform set_config('hamsha.sys', '1', true);
  update posts set current_version = new.number, status = 'draft', sent_at = null where id = new.post_id;
  perform set_config('hamsha.sys', '', true);
  return new;
end $$;

create or replace function decide_post(p_version uuid, p_decision post_decision, p_note text default null)
returns void
language plpgsql security definer set search_path = public as $$
declare v record; p record;
begin
  if current_role_() <> 'client' then raise exception 'only clients decide'; end if;
  select id, post_id, number, decision, sent_at into v from post_versions where id = p_version;
  if v is null then raise exception 'unknown version'; end if;
  select id, org_id, client_id, status, current_version into p from posts where id = v.post_id;
  if p.org_id <> current_org() or p.client_id <> current_client() then raise exception 'not your post'; end if;
  if p.status <> 'sent' then raise exception 'post is not awaiting your decision'; end if;
  if v.number <> p.current_version or v.sent_at is null then raise exception 'only the current sent version can be decided'; end if;
  if v.decision is not null then raise exception 'already decided'; end if;
  if p_decision = 'changes' and length(trim(coalesce(p_note, ''))) = 0 then raise exception 'say what to change'; end if;
  perform set_config('hamsha.sys', '1', true);
  update post_versions set decision = p_decision, decision_note = nullif(trim(coalesce(p_note, '')), ''), decided_by = auth.uid(), decided_at = now() where id = v.id;
  update posts set status = p_decision::text::post_status where id = p.id;
  perform set_config('hamsha.sys', '', true);
end $$;

-- ---------- client views: no drafts, no unsent versions ----------
create view client_posts with (security_invoker = false) as
  select id, client_id, task_id, account_id, title, platform, format, status, current_version, sent_at, published_url, published_at, created_at, updated_at
  from posts
  where current_role_() = 'client' and client_id = current_client() and status <> 'draft';

create view client_post_versions with (security_invoker = false) as
  select v.id, v.post_id, v.number, v.image_paths, v.caption, v.note, v.sent_at, v.decision, v.decision_note, v.decided_at, v.created_at
  from post_versions v
  join posts p on p.id = v.post_id
  where current_role_() = 'client' and p.client_id = current_client() and p.status <> 'draft' and v.sent_at is not null;

revoke all on client_posts, client_post_versions from public, anon;
grant select on client_posts, client_post_versions to authenticated;



-- ================================ 0009_contracts.sql ================================
-- ============================================================================
-- 0009 — «العقود» phase 1 (2026-10-29, built from the manager's own Figma contracts; councils 2026-10-20 + 2026-10-28):
--   • A contract belongs to ONE counterparty: a client (clients.id) or a creative (profiles.id, role creative).
--   • Everything the paper shows lives in a FROZEN version (contracts_versions.content jsonb — parties, sections,
--     pricing, timeline, packages, bank, signers, accent, copyright 1448) with a server-computed sha256 hash.
--     A new version returns the contract to `draft`; the counterparty's decision binds to ONE version number.
--   • Hawamish signs first (admin, on the version), then sends. States (contracts_status_guard, admin only
--     except the two counterparty RPCs): draft → sent → opened → signed | changes | rejected → completed.
--   • Counterparty writes: mark_contract_opened(version) and decide_contract(version, decision, note,
--     signature, signer name + capacity). Signatures are small PNG data URLs stored in the row (no bucket).
--   • Audit: contract_events (who / what / when / user agent) written by the triggers + RPCs; admins read.
--   • Clients never read the raw tables (views client_contracts / client_contract_versions: no drafts, no
--     unsent versions, no internal fields). Creatives read their own contracts through RLS (no drafts).
--   • clients.contract (0001: draft / sent / signed, used by the calendar) is now DERIVED from the latest
--     client contract; clients.contract_block lets the admin block the client's view until signed.
-- Not here (phase 2): e-mail OTP before signing, server-side PDF, licensed signature provider, renewals.
-- ============================================================================

create type contract_kind  as enum ('short', 'full', 'offer');
create type contract_party as enum ('client', 'creative');
create type contract_state as enum ('draft', 'sent', 'opened', 'signed', 'changes', 'rejected', 'completed');
create type contract_decision as enum ('signed', 'changes', 'rejected');

create table contracts (
  id               uuid primary key default gen_random_uuid(),
  org_id           uuid not null references organizations(id) on delete cascade,
  number           integer not null,                                  -- «مسودة #2612», sequential per org
  kind             contract_kind not null default 'full',
  party            contract_party not null default 'client',
  client_id        uuid references clients(id) on delete cascade,
  creative_id      uuid references profiles(id) on delete cascade,
  title            text not null check (length(title) between 1 and 200),
  accent           text not null default '#D9B600' check (accent ~ '^#[0-9A-Fa-f]{6}$'),
  status           contract_state not null default 'draft',
  current_version  integer not null default 0,
  sent_at          timestamptz,
  decided_at       timestamptz,
  created_by       uuid references profiles(id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (org_id, number),
  check ((party = 'client' and client_id is not null and creative_id is null) or (party = 'creative' and creative_id is not null and client_id is null))
);
create index on contracts (org_id, updated_at desc);
create index on contracts (client_id);
create index on contracts (creative_id);

create table contract_versions (
  id               uuid primary key default gen_random_uuid(),
  org_id           uuid not null references organizations(id) on delete cascade,
  contract_id      uuid not null references contracts(id) on delete cascade,
  number           integer not null,
  content          jsonb not null,
  content_hash     text not null,                                      -- sha256(content) — set by the DB
  note             text check (note is null or length(note) <= 2000), -- team → counterparty
  first_signature  text check (first_signature is null or (first_signature like 'data:image/png;base64,%' and length(first_signature) <= 400000)),
  first_signer     text check (first_signer is null or length(first_signer) <= 120),
  first_capacity   text check (first_capacity is null or length(first_capacity) <= 120),
  first_signed_at  timestamptz,
  sent_at          timestamptz,
  opened_at        timestamptz,
  decision         contract_decision,
  decision_note    text check (decision_note is null or length(decision_note) <= 4000),
  signature        text check (signature is null or (signature like 'data:image/png;base64,%' and length(signature) <= 400000)),
  signer_name      text check (signer_name is null or length(signer_name) <= 120),
  signer_capacity  text check (signer_capacity is null or length(signer_capacity) <= 120),
  decided_by       uuid references profiles(id) on delete set null,
  decided_at       timestamptz,
  created_by       uuid references profiles(id) on delete set null,
  created_at       timestamptz not null default now(),
  unique (contract_id, number)
);
create index on contract_versions (contract_id, number desc);

create table contract_events (
  id           bigserial primary key,
  org_id       uuid not null references organizations(id) on delete cascade,
  contract_id  uuid not null references contracts(id) on delete cascade,
  version      integer,
  actor        uuid,
  actor_role   text,
  event        text not null check (event in ('created', 'version', 'first_signed', 'sent', 'withdrawn', 'opened', 'signed', 'changes', 'rejected', 'completed', 'deleted')),
  meta         jsonb not null default '{}'::jsonb,
  at           timestamptz not null default now()
);
create index on contract_events (contract_id, at desc);

alter table clients add column contract_block boolean not null default false;

-- Hawamish's own legal identity for the contract header (CR, address, representative, bank accounts, stamp):
-- typed ONCE by an admin in Settings, never hard-coded in the app (the repository is public).
create table org_legal (
  org_id      uuid primary key references organizations(id) on delete cascade,
  legal       jsonb not null default '{}'::jsonb,
  updated_by  uuid references profiles(id) on delete set null,
  updated_at  timestamptz not null default now()
);
alter table org_legal enable row level security;
revoke all on org_legal from anon;
grant select, insert, update on org_legal to authenticated;
create policy org_legal_admin on org_legal for all
  using (org_id = current_org() and current_role_() = 'admin')
  with check (org_id = current_org() and current_role_() = 'admin');
create or replace function org_legal_touch() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if jsonb_typeof(new.legal) <> 'object' or length(new.legal::text) > 400000 then raise exception 'bad legal profile'; end if;
  new.updated_by := auth.uid(); new.updated_at := now();
  return new;
end $$;
create trigger org_legal_touch before insert or update on org_legal for each row execute function org_legal_touch();

-- ---------- helpers ----------
create or replace function contract_hash(c jsonb) returns text
language sql immutable as $$ select encode(sha256(convert_to(c::text, 'UTF8')), 'hex') $$;

create or replace function log_contract_event(cid uuid, ver integer, ev text, m jsonb default '{}'::jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare o uuid;
begin
  select org_id into o from contracts where id = cid;
  insert into contract_events (org_id, contract_id, version, actor, actor_role, event, meta)
    values (o, cid, ver, auth.uid(), current_role_()::text, ev, coalesce(m, '{}'::jsonb) || jsonb_build_object('ua', left(coalesce(nullif(current_setting('request.headers', true), '')::jsonb ->> 'user-agent', ''), 300)));
end $$;
-- internal only: triggers and the RPCs below call it; nobody calls it from the API
revoke execute on function log_contract_event(uuid, integer, text, jsonb) from public, anon, authenticated;

/** May this user see the contract at all? Admin: org. Creative: own contracts that left draft. Client: never the table. */
create or replace function can_read_contract(cid uuid) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare c record; r user_role := current_role_();
begin
  if auth.uid() is null or r is null or current_org() is null then return false; end if;
  select org_id, party, creative_id, status into c from contracts where id = cid;
  if c is null or c.org_id is distinct from current_org() then return false; end if;
  if r = 'admin' then return true; end if;
  if r = 'creative' then return c.party = 'creative' and c.creative_id = auth.uid() and c.status <> 'draft'; end if;
  return false;
end $$;
revoke execute on function can_read_contract(uuid) from public, anon;
grant  execute on function can_read_contract(uuid) to authenticated;

-- ---------- consistency + the state machine ----------
create or replace function contracts_consistency() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.client_id is not null and not exists (select 1 from clients where id = new.client_id and org_id = new.org_id) then
    raise exception 'client outside organization';
  end if;
  if new.creative_id is not null and not exists (select 1 from profiles where id = new.creative_id and org_id = new.org_id and role = 'creative') then
    raise exception 'counterparty must be a creative of this organization';
  end if;
  if tg_op = 'INSERT' then
    if auth.uid() is null or current_role_() is distinct from 'admin' then raise exception 'only admins create contracts'; end if;
    new.status := 'draft'; new.current_version := 0; new.sent_at := null; new.decided_at := null;
    new.created_by := auth.uid();
    perform 1 from organizations where id = new.org_id for update;   -- one number at a time per organization
    select coalesce(max(number), 2611) + 1 into new.number from contracts where org_id = new.org_id;
  end if;
  return new;
end $$;
create trigger contracts_consistency before insert or update on contracts
  for each row execute function contracts_consistency();

-- (0008 follow-up, Codex review 2026-10-29) a client account linked to posts keeps its platform
create or replace function client_accounts_consistency() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from clients where id = new.client_id and org_id = new.org_id) then
    raise exception 'client outside organization';
  end if;
  if tg_op = 'UPDATE' and (new.id is distinct from old.id or new.org_id is distinct from old.org_id or new.client_id is distinct from old.client_id or new.created_at is distinct from old.created_at) then
    raise exception 'account identity cannot change';
  end if;
  if tg_op = 'UPDATE' and new.platform is distinct from old.platform and exists (select 1 from posts where account_id = new.id) then
    raise exception 'the platform of an account that posts use cannot change';
  end if;
  new.handle := ltrim(trim(new.handle), '@');
  new.updated_at := now();
  return new;
end $$;

create or replace function contracts_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform log_contract_event(new.id, 0, 'created', jsonb_build_object('kind', new.kind, 'party', new.party));
  return new;
end $$;
create trigger contracts_after_insert after insert on contracts
  for each row execute function contracts_after_insert();

-- Allowed transitions (admin only; the counterparty goes through the RPCs which set hamsha.sys).
create or replace function contracts_status_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare sys boolean := coalesce(current_setting('hamsha.sys', true), '') = '1'; v record;
begin
  new.updated_at := now();
  if sys then return new; end if;
  if new.id is distinct from old.id or new.org_id is distinct from old.org_id or new.party is distinct from old.party
     or new.client_id is distinct from old.client_id or new.creative_id is distinct from old.creative_id
     or new.number is distinct from old.number or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception 'contract identity cannot change';
  end if;
  if new.current_version is distinct from old.current_version then raise exception 'current_version is set by saving a version'; end if;
  if auth.uid() is null or current_role_() is distinct from 'admin' then raise exception 'only admins change contracts'; end if;
  if new.status is distinct from old.status then
    if old.status = 'draft' and new.status = 'sent' then
      if old.current_version = 0 then raise exception 'save a version before sending'; end if;
      select first_signature, sent_at into v from contract_versions where contract_id = new.id and number = old.current_version;
      if v.first_signature is null then raise exception 'Hawamish must sign the version before sending'; end if;
      new.sent_at := now();
      perform set_config('hamsha.sys', '1', true);
      update contract_versions set sent_at = coalesce(sent_at, now()) where contract_id = new.id and number = old.current_version;
      perform set_config('hamsha.sys', '', true);
      perform log_contract_event(new.id, old.current_version, 'sent');
    elsif old.status in ('sent', 'opened') and new.status = 'draft' then
      new.sent_at := null;
      perform log_contract_event(new.id, old.current_version, 'withdrawn');
    elsif old.status = 'signed' and new.status = 'completed' then
      perform log_contract_event(new.id, old.current_version, 'completed');
    else
      raise exception 'transition % → % is not allowed', old.status, new.status;
    end if;
  end if;
  if new.sent_at is distinct from old.sent_at and new.status = old.status then raise exception 'sent_at is derived'; end if;
  if new.decided_at is distinct from old.decided_at then raise exception 'decided_at is derived'; end if;
  return new;
end $$;
create trigger contracts_status_guard before update on contracts
  for each row execute function contracts_status_guard();

create or replace function contracts_before_delete() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if old.status in ('signed', 'completed') then raise exception 'a signed contract cannot be deleted'; end if;
  return old;
end $$;
create trigger contracts_before_delete before delete on contracts
  for each row execute function contracts_before_delete();

-- A new version: number + hash assigned here; the contract returns to draft (no decision carries over).
create or replace function contract_versions_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare c record;
begin
  if auth.uid() is null or current_role_() is distinct from 'admin' then raise exception 'only admins write contract versions'; end if;
  select org_id, status, current_version into c from contracts where id = new.contract_id for update;   -- serialises version numbers
  if c is null then raise exception 'unknown contract'; end if;
  if c.org_id <> new.org_id then raise exception 'organization mismatch'; end if;
  if c.status in ('signed', 'completed') then raise exception 'a signed contract cannot change — make a new contract'; end if;
  if jsonb_typeof(new.content) <> 'object' or length(new.content::text) > 400000 then raise exception 'bad content'; end if;
  new.number := c.current_version + 1;
  new.content_hash := contract_hash(new.content);
  new.created_by := auth.uid();
  new.sent_at := null; new.opened_at := null;
  new.first_signature := null; new.first_signer := null; new.first_capacity := null; new.first_signed_at := null;
  new.decision := null; new.decision_note := null; new.signature := null; new.signer_name := null; new.signer_capacity := null; new.decided_by := null; new.decided_at := null;
  perform set_config('hamsha.sys', '1', true);
  update contracts set current_version = new.number, status = 'draft', sent_at = null, decided_at = null where id = new.contract_id;
  perform set_config('hamsha.sys', '', true);
  perform log_contract_event(new.contract_id, new.number, 'version', jsonb_build_object('hash', new.content_hash));
  return new;
end $$;
create trigger contract_versions_insert before insert on contract_versions
  for each row execute function contract_versions_insert();

-- Versions are frozen: only the internal RPCs may touch them.
create or replace function contract_versions_frozen() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if coalesce(current_setting('hamsha.sys', true), '') = '1' then return new; end if;
  raise exception 'contract versions are frozen';
end $$;
create trigger contract_versions_frozen before update on contract_versions
  for each row execute function contract_versions_frozen();

-- A sent, signed or current version is part of the record: it cannot be deleted (the contract itself can,
-- while unsigned, and takes its versions with it).
create or replace function contract_versions_before_delete() returns trigger
language plpgsql security definer set search_path = public as $$
declare c record;
begin
  if coalesce(current_setting('hamsha.sys', true), '') = '1' then return old; end if;
  if old.sent_at is not null or old.first_signature is not null or old.signature is not null then raise exception 'a sent or signed version cannot be deleted'; end if;
  select current_version, status into c from contracts where id = old.contract_id;
  if c is not null and c.current_version = old.number then raise exception 'the current version cannot be deleted'; end if;
  return old;
end $$;
create trigger contract_versions_before_delete before delete on contract_versions
  for each row execute function contract_versions_before_delete();
-- deleting the whole (unsigned) contract still cascades: the FK cascade runs as the system
create or replace function contracts_before_delete() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if old.status in ('signed', 'completed') then raise exception 'a signed contract cannot be deleted'; end if;
  perform set_config('hamsha.sys', '1', true);
  delete from contract_versions where contract_id = old.id;
  perform set_config('hamsha.sys', '', true);
  return old;
end $$;

-- ---------- RPCs ----------
/** Admin: Hawamish signs the CURRENT draft version (before sending). */
create or replace function sign_contract_first(p_version uuid, p_signature text, p_name text, p_capacity text)
returns void
language plpgsql security definer set search_path = public as $$
declare v record; c record;
begin
  if auth.uid() is null or current_role_() is distinct from 'admin' then raise exception 'only admins sign for Hawamish'; end if;
  select id, contract_id, number, sent_at into v from contract_versions where id = p_version;
  if v is null then raise exception 'unknown version'; end if;
  select org_id, status, current_version into c from contracts where id = v.contract_id for update;   -- contract first, then the version
  perform 1 from contract_versions where id = v.id for update;
  if c.org_id is distinct from current_org() then raise exception 'not your contract'; end if;
  if c.status <> 'draft' or v.number <> c.current_version then raise exception 'only the current draft version can be signed'; end if;
  if p_signature is null or p_signature not like 'data:image/png;base64,%' or length(p_signature) > 400000 then raise exception 'bad signature'; end if;
  if length(trim(coalesce(p_name, ''))) = 0 then raise exception 'signer name required'; end if;
  perform set_config('hamsha.sys', '1', true);
  update contract_versions set first_signature = p_signature, first_signer = trim(p_name), first_capacity = nullif(trim(coalesce(p_capacity, '')), ''), first_signed_at = now() where id = v.id;
  perform set_config('hamsha.sys', '', true);
  perform log_contract_event(v.contract_id, v.number, 'first_signed', jsonb_build_object('signer', trim(p_name)));
end $$;
revoke execute on function sign_contract_first(uuid, text, text, text) from public, anon;
grant  execute on function sign_contract_first(uuid, text, text, text) to authenticated;

/** Is the caller the counterparty of this contract? */
create or replace function is_counterparty(p_party contract_party, p_client uuid, p_creative uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select auth.uid() is not null and (
         (p_party = 'client' and current_role_() = 'client' and p_client is not null and p_client = current_client())
      or (p_party = 'creative' and current_role_() = 'creative' and p_creative is not null and p_creative = auth.uid()))
$$;
revoke execute on function is_counterparty(contract_party, uuid, uuid) from public, anon;

/** Counterparty: «فتحت العقد» — first look at the current sent version. */
create or replace function mark_contract_opened(p_version uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v record; c record;
begin
  select id, contract_id into v from contract_versions where id = p_version;
  if v is null then raise exception 'unknown version'; end if;
  select * into c from contracts where id = v.contract_id for update;                      -- contract first …
  select id, contract_id, number, sent_at, opened_at into v from contract_versions where id = p_version for update;   -- … then the version, re-read after the lock
  if c.org_id is distinct from current_org() or is_counterparty(c.party, c.client_id, c.creative_id) is not true then raise exception 'not your contract'; end if;
  if c.status <> 'sent' or v.number <> c.current_version or v.sent_at is null then return; end if;
  perform set_config('hamsha.sys', '1', true);
  update contract_versions set opened_at = coalesce(opened_at, now()) where id = v.id;
  update contracts set status = 'opened' where id = c.id;
  perform set_config('hamsha.sys', '', true);
  perform log_contract_event(c.id, v.number, 'opened');
end $$;
revoke execute on function mark_contract_opened(uuid) from public, anon;
grant  execute on function mark_contract_opened(uuid) to authenticated;

/** Counterparty's ONLY decision: sign (with signature + name + capacity), ask for changes (note required) or reject. */
create or replace function decide_contract(p_version uuid, p_decision contract_decision, p_note text default null, p_signature text default null, p_name text default null, p_capacity text default null)
returns void
language plpgsql security definer set search_path = public as $$
declare v record; c record;
begin
  select id, contract_id into v from contract_versions where id = p_version;
  if v is null then raise exception 'unknown version'; end if;
  select * into c from contracts where id = v.contract_id for update;                      -- contract first …
  select id, contract_id, number, sent_at, decision into v from contract_versions where id = p_version for update;   -- … then the version, re-read after the lock
  if c.org_id is distinct from current_org() or is_counterparty(c.party, c.client_id, c.creative_id) is not true then raise exception 'not your contract'; end if;
  if c.status not in ('sent', 'opened') then raise exception 'contract is not awaiting your decision'; end if;
  if v.number <> c.current_version or v.sent_at is null then raise exception 'only the current sent version can be decided'; end if;
  if v.decision is not null then raise exception 'already decided'; end if;
  if p_decision = 'signed' then
    if p_signature is null or p_signature not like 'data:image/png;base64,%' or length(p_signature) > 400000 then raise exception 'signature required'; end if;
    if length(trim(coalesce(p_name, ''))) = 0 then raise exception 'signer name required'; end if;
  elsif p_decision = 'changes' and length(trim(coalesce(p_note, ''))) = 0 then
    raise exception 'say what to change';
  end if;
  perform set_config('hamsha.sys', '1', true);
  update contract_versions
     set decision = p_decision, decision_note = nullif(trim(coalesce(p_note, '')), ''),
         signature = case when p_decision = 'signed' then p_signature end,
         signer_name = case when p_decision = 'signed' then trim(p_name) end,
         signer_capacity = case when p_decision = 'signed' then nullif(trim(coalesce(p_capacity, '')), '') end,
         decided_by = auth.uid(), decided_at = now()
   where id = v.id;
  update contracts set status = p_decision::text::contract_state, decided_at = now() where id = c.id;
  perform set_config('hamsha.sys', '', true);
  perform log_contract_event(c.id, v.number, p_decision::text, jsonb_build_object('signer', trim(coalesce(p_name, ''))));
end $$;
revoke execute on function decide_contract(uuid, contract_decision, text, text, text, text) from public, anon;
grant  execute on function decide_contract(uuid, contract_decision, text, text, text, text) to authenticated;

-- ---------- clients.contract is derived from the latest client contract ----------
create or replace function contracts_sync_client() returns trigger
language plpgsql security definer set search_path = public as $$
declare cid uuid := coalesce(new.client_id, old.client_id); st contract_state;
begin
  if cid is null then return null; end if;
  select status into st from contracts where client_id = cid and party = 'client' order by updated_at desc limit 1;
  update clients set contract = case when st in ('signed', 'completed') then 'signed' when st in ('sent', 'opened') then 'sent' else 'draft' end::contract_status where id = cid;
  return null;
end $$;
create trigger contracts_sync_client after insert or update of status or delete on contracts
  for each row execute function contracts_sync_client();

-- ---------- RLS ----------
alter table contracts         enable row level security;
alter table contract_versions enable row level security;
alter table contract_events   enable row level security;
revoke all on contracts, contract_versions, contract_events from anon;
grant select, insert, update, delete on contracts, contract_versions to authenticated;
grant select on contract_events to authenticated;

create policy contracts_read on contracts for select
  using (can_read_contract(id));
create policy contracts_admin_write on contracts for all
  using (org_id = current_org() and current_role_() = 'admin')
  with check (org_id = current_org() and current_role_() = 'admin');

create policy cversions_read on contract_versions for select
  using (can_read_contract(contract_id) and (current_role_() = 'admin' or sent_at is not null));
create policy cversions_admin_insert on contract_versions for insert
  with check (org_id = current_org() and current_role_() = 'admin');
create policy cversions_admin_delete on contract_versions for delete
  using (org_id = current_org() and current_role_() = 'admin');

create policy cevents_admin_read on contract_events for select
  using (org_id = current_org() and current_role_() = 'admin');

-- ---------- client views: no drafts, no unsent versions, no internal fields ----------
create view client_contracts with (security_invoker = false) as
  select id, client_id, number, kind, title, accent, status, current_version, sent_at, decided_at, created_at, updated_at
  from contracts
  where current_role_() = 'client' and party = 'client' and client_id = current_client() and status <> 'draft';

create view client_contract_versions with (security_invoker = false) as
  select v.id, v.contract_id, v.number, v.content, v.content_hash, v.note, v.first_signature, v.first_signer, v.first_capacity, v.first_signed_at,
         v.sent_at, v.opened_at, v.decision, v.decision_note, v.signature, v.signer_name, v.signer_capacity, v.decided_at, v.created_at
  from contract_versions v
  join contracts c on c.id = v.contract_id
  where current_role_() = 'client' and c.party = 'client' and c.client_id = current_client() and c.status <> 'draft' and v.sent_at is not null;

revoke all on client_contracts, client_contract_versions from public, anon;
grant select on client_contracts, client_contract_versions to authenticated;

-- ---------- audit + realtime ----------
create trigger contracts_audit  after insert or update or delete on contracts         for each row execute function audit();
create trigger cversions_audit  after insert or update or delete on contract_versions for each row execute function audit();
alter publication supabase_realtime add table contracts, contract_versions;



-- ================================ 0010_hardening.sql ================================
-- =====================================================================================================
-- 0010 — hardening after the full pre-release review (council 20261101-162105-f800, 1 Nov 2026)
--   1. post-media storage: a file is readable only by who may read the VERSION that holds it
--      (before: every creative read every file of the org, and a client could list/download unsent drafts
--      in their folder straight from the Storage API — the client views hid them, the bucket did not).
--   2. decide_post / new versions: the post row is locked first and the version re-read under the lock,
--      like the contract functions (a decision racing a new version could mark the post «approved»
--      while its current version was never approved).
--   3. a version may only reference files inside ITS OWN post folder <org>/<client>/<post>/ (verify round
--      20261101-163636-3a11: a creative could put another client's known path in a version of an allowed post and
--      thereby gain read access to it through can_read_post_media).
-- Safe to re-run.
-- =====================================================================================================

-- ---------- 1. who may read a post-media object ----------
create index if not exists post_versions_image_paths_gin on post_versions using gin (image_paths);

create or replace function can_read_post_media(obj text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1
    from post_versions v
    join posts p on p.id = v.post_id
    where v.org_id = current_org()
      and v.image_paths @> array[obj]
      -- defence in depth (re-verify 20261101-165154-cdd9): the file must also sit in that post's own folder, so a
      -- path borrowed by an OLD version (before the insert check existed) grants nothing
      and obj like v.org_id::text || '/' || p.client_id::text || '/' || p.id::text || '/%'
      and case current_role_()
            when 'admin' then true
            when 'creative' then can_read_post(p.id)
            -- the client sees exactly what client_post_versions shows: sent versions of its own, non-draft posts
            when 'client' then p.client_id = current_client() and p.status <> 'draft' and v.sent_at is not null
            else false
          end
  )
$$;
revoke execute on function can_read_post_media(text) from public, anon;
grant  execute on function can_read_post_media(text) to authenticated;

do $$
begin
  if to_regclass('storage.objects') is null then
    raise notice 'storage schema absent (local CI) — skipping the post-media read policy';
    return;
  end if;
  execute 'drop policy if exists hamsha_post_media_read on storage.objects';
  -- owner_id (not the deprecated `owner`) = the uploader may read what they just uploaded (the version row is inserted right after the upload)
  execute $p$create policy hamsha_post_media_read on storage.objects for select to authenticated
    using (bucket_id = 'post-media' and (storage.foldername(name))[1] = current_org()::text
           and (current_role_() = 'admin' or owner_id = (select auth.uid())::text or can_read_post_media(name)))$p$;
end $$;

-- ---------- 2. decisions and new versions serialise on the post row ----------
create or replace function decide_post(p_version uuid, p_decision post_decision, p_note text default null)
returns void
language plpgsql security definer set search_path = public as $$
declare v record; p record; vid uuid;
begin
  if current_role_() <> 'client' then raise exception 'only clients decide'; end if;
  select post_id into vid from post_versions where id = p_version;
  if vid is null then raise exception 'unknown version'; end if;
  -- post first (a new version takes the same lock in post_versions_insert) …
  select id, org_id, client_id, status, current_version into p from posts where id = vid for update;
  -- … then the version, re-read after the lock
  select id, post_id, number, decision, sent_at into v from post_versions where id = p_version for update;
  if p.org_id <> current_org() or p.client_id <> current_client() then raise exception 'not your post'; end if;
  if p.status <> 'sent' then raise exception 'post is not awaiting your decision'; end if;
  if v.number <> p.current_version or v.sent_at is null then raise exception 'only the current sent version can be decided'; end if;
  if v.decision is not null then raise exception 'already decided'; end if;
  if p_decision = 'changes' and length(trim(coalesce(p_note, ''))) = 0 then raise exception 'say what to change'; end if;
  perform set_config('hamsha.sys', '1', true);
  update post_versions set decision = p_decision, decision_note = nullif(trim(coalesce(p_note, '')), ''), decided_by = auth.uid(), decided_at = now() where id = v.id;
  update posts set status = p_decision::text::post_status where id = p.id;
  perform set_config('hamsha.sys', '', true);
end $$;

create or replace function post_versions_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare p record;
begin
  -- locked: two uploads never get the same number, and a decision in flight finishes before the post moves on
  select org_id, client_id, status, current_version into p from posts where id = new.post_id for update;
  if p is null then raise exception 'unknown post'; end if;
  if p.org_id <> new.org_id then raise exception 'organization mismatch'; end if;
  if p.status = 'published' then raise exception 'a published post cannot change'; end if;
  -- every file must live in this post's own folder (the app uploads to <org>/<client>/<post>/…; kept images of
  -- earlier versions are in the same folder): no borrowing another post's or client's files
  if exists (select 1 from unnest(new.image_paths) x where x not like p.org_id::text || '/' || p.client_id::text || '/' || new.post_id::text || '/%') then
    raise exception 'image path outside this post''s folder';
  end if;
  new.number := p.current_version + 1;
  new.created_by := auth.uid();
  new.sent_at := null;
  new.decision := null; new.decision_note := null; new.decided_by := null; new.decided_at := null;
  perform set_config('hamsha.sys', '1', true);
  update posts set current_version = new.number, status = 'draft', sent_at = null where id = new.post_id;
  perform set_config('hamsha.sys', '', true);
  return new;
end $$;



-- ================================ 0011_hardening2.sql ================================
-- =====================================================================================================
-- 0011 — second hardening pass (councils 20261101-180258-a198 Codex·production, 20261101-180259-4872 Gemini·code,
--        cross-review 20261101-181336-*; every item verified against the code by Claude before it went in)
--   1. decide_post: an UNLINKED client (role client, client_id NULL — e.g. after its client was deleted) passed the
--      ownership check because «x <> NULL» is NULL, not true. Now null-safe and the caller must be a linked client. (Codex)
--   2. storage 0006 (live in production today): any creative could read every file of the «attachments» bucket and
--      overwrite client logos. Attachments now follow the task (can_read_task via the attachments row); logos and
--      attachments are written by admins only (the app never uploads them as a creative). (Codex)
--   3. post-media: the uploader may delete their OWN file while no version references it — the cleanup after a failed
--      «new version» insert was silently refused for creatives and left orphans. (Gemini)
--   4. profiles: a member can only be linked to a client of the SAME organization. (Codex)
--   5. can_access_channel: a malformed «task:…» channel name returns false instead of a uuid cast error. (Gemini)
--   6. clients.contract follows the latest contract the client can SEE (sent/opened/signed/completed); an unsent draft
--      (a renewal being prepared) no longer flips a signed client back to «draft» and trips the block banner. (both)
-- Safe to re-run. Runs after 0010.
-- =====================================================================================================

-- ---------- 1. decide_post: linked clients only, null-safe ownership ----------
create or replace function decide_post(p_version uuid, p_decision post_decision, p_note text default null)
returns void
language plpgsql security definer set search_path = public as $$
declare v record; p record; vid uuid;
begin
  if auth.uid() is null or current_role_() is distinct from 'client' or current_org() is null or current_client() is null then
    raise exception 'only linked clients decide' using errcode = '42501';
  end if;
  select post_id into vid from post_versions where id = p_version;
  if vid is null then raise exception 'unknown version'; end if;
  select id, org_id, client_id, status, current_version into p from posts where id = vid for update;
  select id, post_id, number, decision, sent_at into v from post_versions where id = p_version for update;
  if p.org_id is distinct from current_org() or p.client_id is distinct from current_client() then
    raise exception 'not your post' using errcode = '42501';
  end if;
  if p.status <> 'sent' then raise exception 'post is not awaiting your decision'; end if;
  if v.number <> p.current_version or v.sent_at is null then raise exception 'only the current sent version can be decided'; end if;
  if v.decision is not null then raise exception 'already decided'; end if;
  if p_decision = 'changes' and length(trim(coalesce(p_note, ''))) = 0 then raise exception 'say what to change'; end if;
  perform set_config('hamsha.sys', '1', true);
  update post_versions set decision = p_decision, decision_note = nullif(trim(coalesce(p_note, '')), ''), decided_by = auth.uid(), decided_at = now() where id = v.id;
  update posts set status = p_decision::text::post_status where id = p.id;
  perform set_config('hamsha.sys', '', true);
end $$;

-- ---------- 2 + 3. storage ----------
create or replace function can_read_attachment(obj text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from attachments a where a.org_id = current_org() and a.storage_path = obj and can_read_task(a.task_id))
$$;
revoke execute on function can_read_attachment(text) from public, anon;
grant  execute on function can_read_attachment(text) to authenticated;

-- an object no version points at (a failed upload's leftovers)
create or replace function post_media_unreferenced(obj text) returns boolean
language sql stable security definer set search_path = public as $$
  select not exists (select 1 from post_versions v where v.image_paths @> array[obj])
$$;
revoke execute on function post_media_unreferenced(text) from public, anon;
grant  execute on function post_media_unreferenced(text) to authenticated;

do $$
begin
  if to_regclass('storage.objects') is null then
    raise notice 'storage schema absent (local CI) — skipping storage policies';
    return;
  end if;
  -- client-logos stays a PUBLIC bucket (logos and account avatars are shown by URL); attachments follow their task
  execute 'drop policy if exists hamsha_storage_read on storage.objects';
  execute $p$create policy hamsha_storage_read on storage.objects for select to authenticated
    using ((storage.foldername(name))[1] = current_org()::text
           and (bucket_id = 'client-logos'
                or (bucket_id = 'attachments' and (current_role_() = 'admin' or can_read_attachment(name)))))$p$;
  execute 'drop policy if exists hamsha_storage_write on storage.objects';
  execute $p$create policy hamsha_storage_write on storage.objects for insert to authenticated
    with check (bucket_id in ('client-logos', 'attachments') and (storage.foldername(name))[1] = current_org()::text and current_role_() = 'admin')$p$;
  execute 'drop policy if exists hamsha_storage_update on storage.objects';
  execute $p$create policy hamsha_storage_update on storage.objects for update to authenticated
    using (bucket_id in ('client-logos', 'attachments') and (storage.foldername(name))[1] = current_org()::text and current_role_() = 'admin')
    with check (bucket_id in ('client-logos', 'attachments') and (storage.foldername(name))[1] = current_org()::text and current_role_() = 'admin')$p$;

  execute 'drop policy if exists hamsha_post_media_delete on storage.objects';
  execute $p$create policy hamsha_post_media_delete on storage.objects for delete to authenticated
    using (bucket_id = 'post-media' and (storage.foldername(name))[1] = current_org()::text
           and (current_role_() = 'admin' or (owner_id = (select auth.uid())::text and post_media_unreferenced(name))))$p$;
end $$;

-- ---------- 4. a member is linked only to a client of the same organization ----------
create or replace function profiles_identity_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.id is distinct from old.id or new.org_id is distinct from old.org_id or new.email is distinct from old.email then
    raise exception 'profile identity cannot change';
  end if;
  if current_role_() <> 'admin' and (new.role is distinct from old.role or new.client_id is distinct from old.client_id) then
    raise exception 'only admins change roles';
  end if;
  if new.client_id is not null and new.client_id is distinct from old.client_id
     and not exists (select 1 from clients where id = new.client_id and org_id = new.org_id) then
    raise exception 'client outside organization';
  end if;
  return new;
end $$;

-- ---------- 5. channel names are validated before any cast (exact 8-4-4-4-12 uuid shape — cross-review) ----------
create or replace function can_access_channel(ch text) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare r user_role := current_role_();
begin
  if ch = 'team' then return r in ('admin', 'creative'); end if;
  if ch ~ '^client:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
    return r = 'admin' or (r = 'client' and current_client()::text = substring(ch from 8));
  end if;
  if ch ~ '^task:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
    return r in ('admin', 'creative') and can_read_task(substring(ch from 6)::uuid);
  end if;
  return false;
end $$;

-- ---------- 6. the client's contract state comes from what the client can see ----------
create or replace function contracts_sync_client() returns trigger
language plpgsql security definer set search_path = public as $$
declare cid uuid := coalesce(new.client_id, old.client_id); st contract_state;
begin
  if cid is null then return null; end if;
  -- sent/opened/signed/completed first (newest of those); only when every contract is still a draft → draft
  select status into st from contracts where client_id = cid and party = 'client'
    order by (status <> 'draft') desc, updated_at desc, id desc limit 1;   -- id: a stable tie-break
  update clients set contract = case when st in ('signed', 'completed') then 'signed' when st in ('sent', 'opened') then 'sent' else 'draft' end::contract_status where id = cid;
  return null;
end $$;



-- ================================ 0012_keep_sent_visible.sql ================================
-- =====================================================================================================
-- 0012 — what was SENT stays visible while the team works on a new version (Yousef's decision, 1 Nov 2026,
--        after council 20261101-180259-4872 raised it and 20261101-181336-d8a6 called it a design choice)
-- Before: a new version (or a withdraw) sent the post/contract back to «draft», and the client/creative lost the
--         whole thing — earlier versions, their own decision and note — until it was re-sent: it felt deleted.
-- Now:    anything the counterparty has ever RECEIVED (a version with sent_at) stays in their list with its sent
--         versions; the app shows it as «قيد التعديل». Nothing that was never sent becomes visible: unsent versions
--         and never-sent contracts/posts stay hidden exactly as before. Decisions still need status «sent».
-- Safe to re-run. Runs after 0011.
-- =====================================================================================================

-- ---------- posts ----------
create or replace view client_posts with (security_invoker = false) as
  select p.id, p.client_id, p.task_id, p.account_id, p.title, p.platform, p.format, p.status, p.current_version, p.sent_at,
         p.published_url, p.published_at, p.created_at, p.updated_at
  from posts p
  where current_role_() = 'client' and p.client_id = current_client()
    and (p.status <> 'draft' or exists (select 1 from post_versions v where v.post_id = p.id and v.sent_at is not null));

create or replace view client_post_versions with (security_invoker = false) as
  select v.id, v.post_id, v.number, v.image_paths, v.caption, v.note, v.sent_at, v.decision, v.decision_note, v.decided_at, v.created_at
  from post_versions v
  join posts p on p.id = v.post_id
  where current_role_() = 'client' and p.client_id = current_client() and v.sent_at is not null;

-- the images follow the same rule: a client reads the files of its SENT versions, whatever the post's state now
create or replace function can_read_post_media(obj text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1
    from post_versions v
    join posts p on p.id = v.post_id
    where v.org_id = current_org()
      and v.image_paths @> array[obj]
      and obj like v.org_id::text || '/' || p.client_id::text || '/' || p.id::text || '/%'
      and case current_role_()
            when 'admin' then true
            when 'creative' then can_read_post(p.id)
            when 'client' then p.client_id = current_client() and v.sent_at is not null
            else false
          end
  )
$$;

-- ---------- contracts ----------
create or replace view client_contracts with (security_invoker = false) as
  select c.id, c.client_id, c.number, c.kind, c.title, c.accent, c.status, c.current_version, c.sent_at, c.decided_at, c.created_at, c.updated_at
  from contracts c
  where current_role_() = 'client' and c.party = 'client' and c.client_id = current_client()
    and (c.status <> 'draft' or exists (select 1 from contract_versions v where v.contract_id = c.id and v.sent_at is not null));

create or replace view client_contract_versions with (security_invoker = false) as
  select v.id, v.contract_id, v.number, v.content, v.content_hash, v.note, v.first_signature, v.first_signer, v.first_capacity, v.first_signed_at,
         v.sent_at, v.opened_at, v.decision, v.decision_note, v.signature, v.signer_name, v.signer_capacity, v.decided_at, v.created_at
  from contract_versions v
  join contracts c on c.id = v.contract_id
  where current_role_() = 'client' and c.party = 'client' and c.client_id = current_client() and v.sent_at is not null;

-- a creative counterparty: same rule through the table policies (contract readable once something was sent to them)
create or replace function can_read_contract(cid uuid) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare c record; r user_role := current_role_();
begin
  if auth.uid() is null or r is null or current_org() is null then return false; end if;
  select org_id, party, creative_id, status into c from contracts where id = cid;
  if c is null or c.org_id is distinct from current_org() then return false; end if;
  if r = 'admin' then return true; end if;
  if r = 'creative' then
    return c.party = 'creative' and c.creative_id = auth.uid()
       and (c.status <> 'draft' or exists (select 1 from contract_versions v where v.contract_id = cid and v.sent_at is not null));
  end if;
  return false;
end $$;



-- ================================ 0013_employment_contract.sql ================================
-- «عقد عمل» (1 Nov 2026): the employment contract for a full-time creative (the manager's Figma page «عقود الموظفين»).
-- Only a new template kind: the rows, rights and signing flow are the same as every other contract (party = 'creative').
alter type contract_kind add value if not exists 'employment';



-- ================================ 0014_contract_integrity.sql ================================
-- 0014 contract + activity integrity (overnight council 20261101-233827-bff0, Codex findings 1, 2, 5; 2 Nov 2026)
-- 1. The database itself refuses to SIGN or SEND a contract whose CORE is empty (title, date, both names, signer).
--    Every other empty printed field is a warning (Yousef 2 Nov: sign anyway is allowed) recorded in the trail.
-- 2. A version that already reached the other side can never be re-signed: after «سحب» a new signature needs a NEW
--    version, so the copy the client/creative already saw keeps its signature and date.
-- 3. posts.sent_by / posts.published_by: who clicked «أرسل للعميل» / «تم النشر», so a second admin's alerts can show
--    the other admin's moves (never exposed to clients: client_posts lists its columns explicitly).

-- small helpers: an empty text at a path / a positive number at a path (JSON numbers only)
create or replace function _c_empty(c jsonb, path text[]) returns boolean
language sql immutable set search_path = public as $$ select length(trim(coalesce(c #>> path, ''))) = 0 $$;
create or replace function _c_pos(c jsonb, path text[]) returns boolean
language sql immutable set search_path = public as $$
  select case when jsonb_typeof(c #> path) = 'number' then (c #>> path)::numeric > 0 else false end $$;

/** Every field the paper prints that is still empty (Arabic labels, form order) — mirrors missingFields() in
 *  src/lib/contracts.ts. 2 Nov (Yousef: «أي نقص… يقلي ترا عندك كذا فاضي… وأقدر أوقّع على أي حال»): these are
 *  WARNINGS; signing anyway is allowed and the list is written into the contract's trail. Only contract_core_missing()
 *  blocks. */
create or replace function contract_content_gaps(c jsonb) returns text[]
language plpgsql immutable set search_path = public as $$
declare k text := coalesce(c ->> 'kind', '');
  g text[] := '{}';
  txt text;
  side text; who text;
  i int;
  body text; w text; wempty boolean;
begin
  if c is null then return array['المحتوى']; end if;
  if _c_empty(c, '{title}') then g := array_append(g, 'عنوان العقد'); end if;
  if coalesce(c ->> 'date', '') !~ '^\d{4}-\d{2}-\d{2}$' then g := array_append(g, 'تاريخ العقد'); end if;
  if k = 'employment' then
    if _c_empty(c, '{jobTitle}') then g := array_append(g, 'الوظيفة'); end if;
    if _c_empty(c, '{counterparty,name}') then g := array_append(g, 'اسم الموظف'); end if;
    if _c_empty(c, '{counterparty,nationalId}') then g := array_append(g, 'رقم هوية الموظف'); end if;
    if _c_empty(c, '{counterparty,phone}') then g := array_append(g, 'رقم التواصل (الموظف)'); end if;
    if _c_empty(c, '{counterparty,email}') then g := array_append(g, 'إيميل التواصل (الموظف)'); end if;
    if _c_empty(c, '{hawamish,name}') then g := array_append(g, 'اسم هوامش'); end if;
    if _c_empty(c, '{hawamish,cr}') then g := array_append(g, 'السجل التجاري (هوامش)'); end if;
    if _c_empty(c, '{hawamish,repName}') then g := array_append(g, 'ممثل هوامش'); end if;
    if _c_empty(c, '{hawamish,phone}') then g := array_append(g, 'رقم التواصل (هوامش)'); end if;
    if _c_empty(c, '{hawamish,email}') then g := array_append(g, 'إيميل التواصل (هوامش)'); end if;
    if _c_empty(c, '{bank,owner}') then g := array_append(g, 'صاحب الحساب (الموظف)'); end if;
    if _c_empty(c, '{bank,account}') then g := array_append(g, 'رقم الحساب (الموظف)'); end if;
    if _c_empty(c, '{bank,iban}') then g := array_append(g, 'آيبان الموظف'); end if;
  else
    -- the words the contract TEXT uses must be filled (unused counts stay optional), like the editor's bar
    -- the scope (short / offer) + EVERY clause, incl. the ones the team added (2 Nov)
    select coalesce(case when k = 'full' then '' else c ->> 'scope' end, '') || E'\n' || coalesce(string_agg(x ->> 'body', E'\n'), '')
      into txt from jsonb_array_elements(coalesce(c -> 'sections', '[]'::jsonb)) x;
    if position('{الهدف}' in txt) > 0 and _c_empty(c, '{project}') then g := array_append(g, 'المشروع'); end if;
    foreach side in array array['counterparty', 'hawamish'] loop
      who := case side when 'counterparty' then 'الطرف الآخر' else 'هوامش' end;
      if _c_empty(c, array[side, 'name']) then g := array_append(g, 'اسم ' || who); end if;
      if _c_empty(c, array[side, 'cr']) then g := array_append(g, 'السجل التجاري (' || who || ')'); end if;
      if _c_empty(c, array[side, 'nationalId']) then g := array_append(g, 'الهوية الوطنية (' || who || ')'); end if;
      if k <> 'short' and _c_empty(c, array[side, 'city']) then g := array_append(g, 'المدينة (' || who || ')'); end if;
      if _c_empty(c, array[side, 'repName']) then g := array_append(g, 'الممثل (' || who || ')'); end if;
      if _c_empty(c, array[side, 'phone']) then g := array_append(g, 'رقم التواصل (' || who || ')'); end if;
      if _c_empty(c, array[side, 'email']) then g := array_append(g, 'إيميل التواصل (' || who || ')'); end if;
    end loop;
    if position('{المنصات}' in txt) > 0 and _c_empty(c, '{vars,platforms}') then g := array_append(g, 'المنصات'); end if;
    if position('{المنشورات}' in txt) > 0 and not _c_pos(c, '{vars,posts}') then g := array_append(g, 'عدد المنشورات شهرياً'); end if;
    if position('{التصاميم}' in txt) > 0 and not _c_pos(c, '{vars,designs}') then g := array_append(g, 'عدد التصاميم شهرياً'); end if;
    if position('{الفيديوهات}' in txt) > 0 and not _c_pos(c, '{vars,videos}') then g := array_append(g, 'عدد الفيديوهات شهرياً'); end if;
    if k = 'short' then
      if jsonb_array_length(coalesce(c -> 'tracks', '[]'::jsonb)) = 0 then g := array_append(g, 'المسار'); end if;
      for i in 0 .. jsonb_array_length(coalesce(c -> 'tracks', '[]'::jsonb)) - 1 loop
        if not _c_pos(c, array['tracks', i::text, 'monthly']) then g := array_append(g, 'المبلغ الشهري للمسار ' || (i + 1)); end if;
        if not _c_pos(c, array['tracks', i::text, 'months']) then g := array_append(g, 'مدة المسار ' || (i + 1)); end if;
      end loop;
    elsif k = 'offer' then
      for i in 0 .. jsonb_array_length(coalesce(c -> 'packages', '[]'::jsonb)) - 1 loop
        if not _c_pos(c, array['packages', i::text, 'price']) then g := array_append(g, 'سعر الباقة ' || (i + 1)); end if;
      end loop;
    elsif coalesce(c #>> '{pricing,mode}', 'monthly') = 'monthly' then
      if not _c_pos(c, '{pricing,monthly}') then g := array_append(g, 'المبلغ الشهري'); end if;
      if not _c_pos(c, '{pricing,months}') then g := array_append(g, 'عدد الأشهر'); end if;
    else
      if not (_c_pos(c, '{pricing,projectTotal}') or exists (
              select 1 from jsonb_array_elements(coalesce(c #> '{pricing,installments}', '[]'::jsonb)) x
              where jsonb_typeof(x -> 'amount') = 'number' and (x ->> 'amount')::numeric > 0)) then g := array_append(g, 'إجمالي المشروع'); end if;
      if exists (select 1 from jsonb_array_elements(coalesce(c #> '{pricing,installments}', '[]'::jsonb)) x
                 where not (jsonb_typeof(x -> 'amount') = 'number' and (x ->> 'amount')::numeric > 0)) then g := array_append(g, 'مبالغ الدفعات'); end if;
    end if;
    if _c_empty(c, '{bank,iban}') then g := array_append(g, 'الآيبان (الحساب البنكي)'); end if;
  end if;
  -- a clause with no title / no text (the full template's pricing clause 04 is generated, never empty)
  for i in 0 .. jsonb_array_length(coalesce(c -> 'sections', '[]'::jsonb)) - 1 loop
    if _c_empty(c, array['sections', i::text, 'title']) then
      g := array_append(g, 'عنوان البند ' || coalesce(c #>> array['sections', i::text, 'num'], (i + 1)::text));
    elsif not (k = 'full' and coalesce(c #>> array['sections', i::text, 'key'], c #>> array['sections', i::text, 'num']) = '04')
          and _c_empty(c, array['sections', i::text, 'body']) then
      g := array_append(g, 'نص البند ' || coalesce(c #>> array['sections', i::text, 'num'], (i + 1)::text));
    end if;
    -- a {word} this template has no field for, left empty (e.g. {التصاميم} typed into a «عقد عمل») — mirrors clauseGaps()
    body := coalesce(c #>> array['sections', i::text, 'body'], '');
    foreach w in array array['الهدف', 'المنصات', 'المنشورات', 'التصاميم', 'الفيديوهات', 'الوظيفة'] loop
      -- (computed apart: a plpgsql IF condition ends at its first THEN, so no CASE inside it)
      wempty := case w when 'الهدف' then _c_empty(c, '{project}') when 'المنصات' then _c_empty(c, '{vars,platforms}')
                       when 'المنشورات' then not _c_pos(c, '{vars,posts}') when 'التصاميم' then not _c_pos(c, '{vars,designs}')
                       when 'الفيديوهات' then not _c_pos(c, '{vars,videos}') else _c_empty(c, '{jobTitle}') end;
      if position('{' || w || '}' in body) > 0
         and ((k = 'employment' and w <> 'الوظيفة') or (k <> 'employment' and w = 'الوظيفة'))
         and wempty then
        g := array_append(g, '{' || w || '} في البند ' || coalesce(c #>> array['sections', i::text, 'num'], (i + 1)::text));
      end if;
    end loop;
  end loop;
  if _c_empty(c, '{signers,hawamish,name}') then g := array_append(g, 'اسم موقّع هوامش'); end if;
  return g;
end $$;

/** The first gap (NULL when none) — kept for the release check and messages. */
create or replace function contract_content_missing(c jsonb) returns text
language sql immutable set search_path = public as $$ select (contract_content_gaps(c))[1] $$;

/** What makes a paper meaningless — the only things that BLOCK signing and sending. */
create or replace function contract_core_missing(c jsonb) returns text
language plpgsql immutable set search_path = public as $$
begin
  if c is null then return 'المحتوى'; end if;
  if _c_empty(c, '{title}') then return 'عنوان العقد'; end if;
  if coalesce(c ->> 'date', '') !~ '^\d{4}-\d{2}-\d{2}$' then return 'تاريخ العقد'; end if;
  if _c_empty(c, '{counterparty,name}') then return 'اسم الطرف الآخر'; end if;
  if _c_empty(c, '{hawamish,name}') then return 'اسم هوامش'; end if;
  if _c_empty(c, '{signers,hawamish,name}') then return 'اسم موقّع هوامش'; end if;
  return null;
end $$;

create or replace function contracts_status_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare sys boolean := coalesce(current_setting('hamsha.sys', true), '') = '1'; v record; miss text;
begin
  new.updated_at := now();
  if sys then return new; end if;
  if new.id is distinct from old.id or new.org_id is distinct from old.org_id or new.party is distinct from old.party
     or new.client_id is distinct from old.client_id or new.creative_id is distinct from old.creative_id
     or new.number is distinct from old.number or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception 'contract identity cannot change';
  end if;
  if new.current_version is distinct from old.current_version then raise exception 'current_version is set by saving a version'; end if;
  if auth.uid() is null or current_role_() is distinct from 'admin' then raise exception 'only admins change contracts'; end if;
  if new.status is distinct from old.status then
    if old.status = 'draft' and new.status = 'sent' then
      if old.current_version = 0 then raise exception 'save a version before sending'; end if;
      select first_signature, sent_at, content into v from contract_versions where contract_id = new.id and number = old.current_version;
      if v.first_signature is null then raise exception 'Hawamish must sign the version before sending'; end if;
      -- 0014: never send an incomplete contract. Checked on the FIRST send only: a version that already went out once
      -- (re-sent after «سحب») keeps the content it was sent with (council verify round, 2 Nov)
      if v.sent_at is null then
        miss := contract_core_missing(v.content);
        if miss is not null then raise exception 'contract incomplete: %', miss; end if;
      end if;
      new.sent_at := now();
      perform set_config('hamsha.sys', '1', true);
      update contract_versions set sent_at = coalesce(sent_at, now()) where contract_id = new.id and number = old.current_version;
      perform set_config('hamsha.sys', '', true);
      perform log_contract_event(new.id, old.current_version, 'sent');
    elsif old.status in ('sent', 'opened') and new.status = 'draft' then
      new.sent_at := null;
      perform log_contract_event(new.id, old.current_version, 'withdrawn');
    elsif old.status = 'signed' and new.status = 'completed' then
      perform log_contract_event(new.id, old.current_version, 'completed');
    else
      raise exception 'transition % → % is not allowed', old.status, new.status;
    end if;
  end if;
  if new.sent_at is distinct from old.sent_at and new.status = old.status then raise exception 'sent_at is derived'; end if;
  if new.decided_at is distinct from old.decided_at then raise exception 'decided_at is derived'; end if;
  return new;
end $$;

/** Admin: Hawamish signs the CURRENT draft version (before sending) — never one already sent, never an incomplete one. */
create or replace function sign_contract_first(p_version uuid, p_signature text, p_name text, p_capacity text)
returns void
language plpgsql security definer set search_path = public as $$
declare v record; c record; miss text; gaps text[];
begin
  if auth.uid() is null or current_role_() is distinct from 'admin' then raise exception 'only admins sign for Hawamish'; end if;
  select id, contract_id, number, sent_at into v from contract_versions where id = p_version;
  if v is null then raise exception 'unknown version'; end if;
  select org_id, status, current_version into c from contracts where id = v.contract_id for update;   -- contract first, then the version
  perform 1 from contract_versions where id = v.id for update;
  select sent_at into v.sent_at from contract_versions where id = v.id;                               -- re-read under the lock
  if c.org_id is distinct from current_org() then raise exception 'not your contract'; end if;
  if c.status <> 'draft' or v.number <> c.current_version then raise exception 'only the current draft version can be signed'; end if;
  if v.sent_at is not null then raise exception 'this version was already sent — save a new version to sign again'; end if;
  select contract_core_missing(content), contract_content_gaps(content) into miss, gaps from contract_versions where id = v.id;
  if miss is not null then raise exception 'contract incomplete: %', miss; end if;
  if p_signature is null or p_signature not like 'data:image/png;base64,%' or length(p_signature) > 400000 then raise exception 'bad signature'; end if;
  if length(trim(coalesce(p_name, ''))) = 0 then raise exception 'signer name required'; end if;
  perform set_config('hamsha.sys', '1', true);
  update contract_versions set first_signature = p_signature, first_signer = trim(p_name), first_capacity = nullif(trim(coalesce(p_capacity, '')), ''), first_signed_at = now() where id = v.id;
  perform set_config('hamsha.sys', '', true);
  -- signed knowingly with empty fields → the trail says which (his choice: warn, never block)
  perform log_contract_event(v.contract_id, v.number, 'first_signed', jsonb_build_object('signer', trim(p_name))
    || case when coalesce(array_length(gaps, 1), 0) > 0 then jsonb_build_object('gaps', to_jsonb(gaps)) else '{}'::jsonb end);
end $$;
revoke execute on function sign_contract_first(uuid, text, text, text) from public, anon;
grant  execute on function sign_contract_first(uuid, text, text, text) to authenticated;

-- ---------- 3. who sent / published a post ----------
alter table posts add column if not exists sent_by uuid;
alter table posts add column if not exists published_by uuid;
create or replace function posts_actor_stamp() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.sent_by := null; new.published_by := null;
    return new;
  end if;
  -- only this trigger writes them: whatever a request sends is replaced by the real actor of the status change
  new.sent_by := case when new.status = 'sent' and old.status is distinct from 'sent' then auth.uid() else old.sent_by end;
  new.published_by := case when new.status = 'published' and old.status is distinct from 'published' then auth.uid() else old.published_by end;
  return new;
end $$;
drop trigger if exists posts_actor_stamp on posts;
create trigger posts_actor_stamp before insert or update on posts
  for each row execute function posts_actor_stamp();



-- ---------- final check: anything missing or any old row lost → rollback everything ----------
do $$
declare miss text := '';
begin
  if to_regclass('public.posts') is null then miss := miss || ' posts'; end if;
  if to_regclass('public.post_versions') is null then miss := miss || ' post_versions'; end if;
  if to_regclass('public.client_accounts') is null then miss := miss || ' client_accounts'; end if;
  if to_regclass('public.contracts') is null then miss := miss || ' contracts'; end if;
  if to_regclass('public.contract_versions') is null then miss := miss || ' contract_versions'; end if;
  if to_regclass('public.contract_events') is null then miss := miss || ' contract_events'; end if;
  if to_regclass('public.org_legal') is null then miss := miss || ' org_legal'; end if;
  if to_regclass('public.client_posts') is null then miss := miss || ' client_posts'; end if;
  if to_regclass('public.client_contracts') is null then miss := miss || ' client_contracts'; end if;
  if to_regprocedure('public.can_read_post_media(text)') is null then miss := miss || ' can_read_post_media'; end if;
  if to_regprocedure('public.can_read_attachment(text)') is null then miss := miss || ' can_read_attachment'; end if;
  if to_regprocedure('public.decide_contract(uuid,contract_decision,text,text,text,text)') is null then miss := miss || ' decide_contract'; end if;
  if not exists (select 1 from information_schema.columns where table_name = 'clients' and column_name = 'contract_block') then miss := miss || ' clients.contract_block'; end if;
  if to_regprocedure('public.contract_content_missing(jsonb)') is null then miss := miss || ' contract_content_missing'; end if;
  if to_regprocedure('public.contract_core_missing(jsonb)') is null then miss := miss || ' contract_core_missing'; end if;
  if not exists (select 1 from information_schema.columns where table_name = 'posts' and column_name = 'published_by') then miss := miss || ' posts.published_by'; end if;
  if not exists (select 1 from pg_enum e join pg_type t on t.oid = e.enumtypid where t.typname = 'contract_kind' and e.enumlabel = 'employment') then miss := miss || ' contract_kind.employment'; end if;
  if miss <> '' then raise exception 'RELEASE ROLLED BACK — missing:%', miss; end if;
  if exists (select 1 from release_before b
             join (values ('organizations', (select count(*) from organizations)), ('profiles', (select count(*) from profiles)), ('clients', (select count(*) from clients)), ('projects', (select count(*) from projects)), ('tasks', (select count(*) from tasks)), ('task_parts', (select count(*) from task_parts)), ('messages', (select count(*) from messages)), ('invitations', (select count(*) from invitations)), ('attachments', (select count(*) from attachments))) a(tbl, n) on a.tbl = b.tbl
             where a.n < b.n) then
    raise exception 'RELEASE ROLLED BACK — an old table lost rows';
  end if;
end $$;

select 'Hamsha release 0007–0014 OK' as result,
       (select count(*) from profiles) as profiles, (select count(*) from clients) as clients, (select count(*) from tasks) as tasks;
commit;
